import time


def select_cases(all_cases, selected_ids):
    if not selected_ids:
        return all_cases
    seen = set()
    selected = []
    for cid in selected_ids:
        if cid in seen:
            continue
        seen.add(cid)
        for case in all_cases:
            if case["id"] == cid:
                selected.append(case)
                break
        else:
            raise ValueError(f"Unknown case ID: {cid}")
    return selected

